@startuml

class User {
  +id : string
  +name : string
  +address : string
  +birthday : date
}

class BusinessOwner extends User {
  +linkedin_account : string
}

class HungryCustomer extends User {
  +delivery_address : string
}

class Entertainer extends User {
  +stage_name : string
  +bio : string
  +price_per_30_minutes : float
}

class PizzaRestaurant {
  +zip_code : string
  +address : string
  +phone_number : string
  +website : string
  +opening_hours : string
}

class Pizza {
  +name : string
  +crust_structure : string
  +price : double
}

class Order {
  +id : string
  +placed_at : datetime
  +latest_delivery_time : time
  +number_of_people : int
}

class EntertainmentOrder extends Order {
  +entertainment_type : string
  +duration : int
}

class EntertainerAvailability {
  +day : string
}

BusinessOwner "1" -- "*" PizzaRestaurant : owns
PizzaRestaurant "1" -- "*" Pizza : offers
PizzaRestaurant "1" -- "*" Order : receives
PizzaRestaurant "1" -- "*" EntertainerAvailability : has
Entertainer "1" -- "*" EntertainerAvailability : provides
Entertainer "1" -- "*" EntertainmentOrder : fulfills
HungryCustomer "1" -- "*" Order : makes
Order "*" -- "1..*" Pizza : contains

@enduml

